    const notify=message=>{if(output)output.textContent=message||'';if(options.notify&&message)options.notify(message);};
    const patch=async change=>{try{await store.updateProject(change);}catch(e){notify('No se ha podido guardar: '+e.message);}};
    const getSelection=()=>((store.getProject().selectedReferences)||[]).filter(item=>map.has(refOf(item)));
